import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Discord bot","description":"","frontmatter":{"pageId":"admins/discord","contentRevision":1},"headers":[],"relativePath":"en/admins/discord.md","filePath":"en/admins/discord.md"}'),s={name:"en/admins/discord.md"};function n(o,e,d,l,c,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="discord-bot" tabindex="-1">Discord bot <a class="header-anchor" href="#discord-bot" aria-label="Permalink to &quot;Discord bot&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>The bot is a separate process/container configured under RimlinkBot. Server.Url points to server HTTPS; ApiToken is a separate named server token with the necessary scopes. StateFile persists the feed position and needs persistent storage.</p><p>Create a bot in the Discord Developer Portal, enable the required Message Content intent for chat bridging, and add it to the chosen guild with least permissions. Set Discord.Token, GuildId, Language (en/ru), ModeratorRoleIds, AdminRoleIds and channel IDs for Server/Raids/Market/Moderation/Chat. Zero IDs in the sample are not a working configuration.</p><p>Configure CertificateSha256 (pin), or a trusted chain with CertificateName where needed. Test status reads, role restrictions and public chat in a test channel before enabling the bridge.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Discord.Token and Server.ApiToken are different secrets. Insecure defaults to false; true is only for isolation. Server scopes and Discord roles are independent. The bridge relays public chat, not direct/alliance messages. Restart/gaps require state refresh, not invented missing events.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./security-auth">TLS, authentication and permissions</a></li><li><a href="./monitoring">Monitoring and event feed</a></li><li><a href="./../players/chat-pings">Chat, messages and pings</a></li></ul>',10)])])}const m=a(s,[["render",n]]);export{u as __pageData,m as default};
